use stdpython :: * ; pub fn example () -> Result < i64 , PyException > { print_parts (& [py_display (& ("sys.executable:")) , py_display (& ((* sys :: executable)))] , " " , "\n") ; print_parts (& [py_display (& ("sys.argv:")) , py_display (& ((* sys :: argv)))] , " " , "\n") ; return Ok (42) ; } fn __module_init__ () -> Result < () , PyException > { let obj ; ; obj = example () ? ; ; sys :: exit (obj) ; Ok (()) } fn main () { if let Err (e) = __module_init__ () { eprintln ! ("{}" , e) ; std :: process :: exit (1) ; } }